def regions(path, start=0, end=None, blk=1024*1024):
    f=open(path,'rb'); f.seek(0,2); size=f.tell()
    if end is None or end>size: end=size
    f.seek(start)
    pos=start; cur=None; out=[]; total=0
    while pos<end:
        b=f.read(min(blk,end-pos))
        if not b: break
        nz = b.rstrip(b'\0') != b''
        if nz:
            total+=1
            if cur is None: cur=pos
        else:
            if cur is not None: out.append((cur,pos-cur)); cur=None
        pos+=len(b)
    if cur is not None: out.append((cur,pos-cur))
    return out,total
for path,start in [('/run/mount/disk3.dd',0),('/home/jeremy/image.dd',9*1024**3)]:
    out,total=regions(path,start)
    print(f"== {path} (from {start}): {total} MiB non-zero, {len(out)} regions")
    for s,l in out[:20]: print(f"   {s} (+{l//1048576}MiB)  {round(s/1024**3,2)}GiB")
